import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { TaskService } from '../../services/task.service';
import { Task, TaskStatus, TaskPriority } from '../../models/task.model';

@Component({
  selector: 'app-task-list',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './task-list.component.html',
  styleUrls: ['./task-list.component.css']
})
export class TaskListComponent implements OnInit {

  tasks: Task[] = [];
  filteredTasks: Task[] = [];
  loading = false;
  error: string | null = null;

  // Filters
  selectedStatus: string = '';
  selectedPriority: string = '';
  searchTerm: string = '';

  // Enums for template
  TaskStatus = TaskStatus;
  TaskPriority = TaskPriority;

  statusOptions = Object.values(TaskStatus);
  priorityOptions = Object.values(TaskPriority);

  selectedTask: Task | null = null;
  showForm = false;

  constructor(private taskService: TaskService) { }

  ngOnInit(): void {
    this.loadTasks();
  }

  loadTasks(): void {
    this.loading = true;
    this.error = null;

    this.taskService.getAllTasks().subscribe({
      next: (data) => {
        this.tasks = data;
        this.applyFilters();
        this.loading = false;
      },
      error: (err) => {
        this.error = 'Failed to load tasks: ' + (err.error?.message || err.message);
        this.loading = false;
        console.error('Error loading tasks:', err);
      }
    });
  }

  applyFilters(): void {
    this.filteredTasks = this.tasks.filter(task => {
      const matchStatus = !this.selectedStatus || task.status === this.selectedStatus;
      const matchPriority = !this.selectedPriority || task.priority === this.selectedPriority;
      const matchSearch = !this.searchTerm || 
        task.title.toLowerCase().includes(this.searchTerm.toLowerCase()) ||
        (task.description && task.description.toLowerCase().includes(this.searchTerm.toLowerCase()));

      return matchStatus && matchPriority && matchSearch;
    });
  }

  onFilterChange(): void {
    this.applyFilters();
  }

  selectTask(task: Task): void {
    this.selectedTask = task;
  }

  editTask(task: Task): void {
    this.selectedTask = task;
    this.showForm = true;
  }

  deleteTask(id: number): void {
    if (confirm('Are you sure you want to delete this task?')) {
      this.taskService.deleteTask(id).subscribe({
        next: () => {
          this.loadTasks();
          this.selectedTask = null;
        },
        error: (err) => {
          this.error = 'Failed to delete task: ' + (err.error?.message || err.message);
          console.error('Error deleting task:', err);
        }
      });
    }
  }

  onTaskSaved(): void {
    this.loadTasks();
    this.showForm = false;
    this.selectedTask = null;
  }

  onFormClosed(): void {
    this.showForm = false;
    this.selectedTask = null;
  }

  getPriorityClass(priority: TaskPriority): string {
    switch (priority) {
      case TaskPriority.CRITICAL:
        return 'priority-critical';
      case TaskPriority.HIGH:
        return 'priority-high';
      case TaskPriority.MEDIUM:
        return 'priority-medium';
      case TaskPriority.LOW:
        return 'priority-low';
      default:
        return '';
    }
  }

  getStatusClass(status: TaskStatus): string {
    switch (status) {
      case TaskStatus.COMPLETED:
        return 'status-completed';
      case TaskStatus.IN_PROGRESS:
        return 'status-in-progress';
      case TaskStatus.CANCELLED:
        return 'status-cancelled';
      case TaskStatus.PENDING:
      default:
        return 'status-pending';
    }
  }
}
<div class="task-list-container">
  <div class="header">
    <h1>Task Management System</h1>
    <button class="btn btn-primary" (click)="showForm = true">
      + New Task
    </button>
  </div>

  <!-- Error message -->
  <div *ngIf="error" class="alert alert-error">
    {{ error }}
    <button class="close-btn" (click)="error = null">&times;</button>
  </div>

  <!-- Loading indicator -->
  <div *ngIf="loading" class="loading">
    <div class="spinner"></div>
    <p>Loading tasks...</p>
  </div>

  <!-- Filters -->
  <div class="filters">
    <div class="filter-group">
      <label for="statusFilter">Status:</label>
      <select id="statusFilter" [(ngModel)]="selectedStatus" (change)="onFilterChange()">
        <option value="">All Statuses</option>
        <option *ngFor="let status of statusOptions" [value]="status">
          {{ status }}
        </option>
      </select>
    </div>

    <div class="filter-group">
      <label for="priorityFilter">Priority:</label>
      <select id="priorityFilter" [(ngModel)]="selectedPriority" (change)="onFilterChange()">
        <option value="">All Priorities</option>
        <option *ngFor="let priority of priorityOptions" [value]="priority">
          {{ priority }}
        </option>
      </select>
    </div>

    <div class="filter-group">
      <label for="searchInput">Search:</label>
      <input
        id="searchInput"
        type="text"
        [(ngModel)]="searchTerm"
        (input)="onFilterChange()"
        placeholder="Search by title or description..."
      />
    </div>
  </div>

  <!-- Task Form Modal -->
  <div *ngIf="showForm" class="modal-overlay" (click)="onFormClosed()">
    <div class="modal-content" (click)="$event.stopPropagation()">
      <app-task-form
        [task]="selectedTask"
        (taskSaved)="onTaskSaved()"
        (formClosed)="onFormClosed()"
      ></app-task-form>
    </div>
  </div>

  <!-- Tasks Grid -->
  <div class="tasks-grid" *ngIf="!loading">
    <div *ngIf="filteredTasks.length === 0" class="no-tasks">
      <p>No tasks found. Create your first task!</p>
    </div>

    <div *ngFor="let task of filteredTasks" class="task-card" [ngClass]="getPriorityClass(task.priority)">
      <div class="task-header">
        <h3>{{ task.title }}</h3>
        <div class="task-actions">
          <button class="btn-icon" (click)="editTask(task)" title="Edit">✎</button>
          <button class="btn-icon" (click)="deleteTask(task.id)" title="Delete">🗑</button>
        </div>
      </div>

      <p *ngIf="task.description" class="task-description">{{ task.description }}</p>

      <div class="task-meta">
        <span class="badge" [ngClass]="'badge-' + task.status.toLowerCase()">
          {{ task.status }}
        </span>
        <span class="badge badge-priority" [ngClass]="'priority-' + task.priority.toLowerCase()">
          {{ task.priority }}
        </span>
      </div>

      <div class="task-dates">
        <small>Created: {{ task.createdAt | date: 'short' }}</small>
        <small *ngIf="task.completedAt">Completed: {{ task.completedAt | date: 'short' }}</small>
      </div>
    </div>
  </div>
</div>
